<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { api,unwrap } from '../api/client'
import { useAuthStore } from '../stores/auth'
import { useListQuery } from '../composables/useListQuery'
import MBPageHeader from '../components/MBPageHeader.vue'
import MBStatusTag from '../components/MBStatusTag.vue'

const auth=useAuthStore(); const {query,syncQuery}=useListQuery({status:''}); const rows=ref<any[]>([]); const loading=ref(false); const actionLoading=ref(false)
const drawer=ref(false); const selected=ref<any>(null); const updateDialog=ref(false); const nextStatus=ref('INVESTIGATING'); const note=ref('')
const canRun=computed(()=>auth.hasPermission('RECONCILIATION_RUN')); const canResolve=computed(()=>Boolean(auth.profile?.platformAdmin))
const money=(c:string,v:number|null)=>v==null?'—':new Intl.NumberFormat('zh-CN',{style:'currency',currency:c||'CNY'}).format(v/100)
const evidence=computed(()=>{if(!selected.value?.evidence)return '—';try{return JSON.stringify(JSON.parse(selected.value.evidence),null,2)}catch{return selected.value.evidence}})
async function load(){loading.value=true;try{await syncQuery();rows.value=unwrap(await api.get('/tenant/reconciliation/differences',{params:{status:query.status||undefined,limit:100}}))}finally{loading.value=false}}
async function runReconciliation(){if(actionLoading.value)return;actionLoading.value=true;try{const run=unwrap<any>(await api.post('/tenant/reconciliation/runs',null,{headers:{'Idempotency-Key':crypto.randomUUID()}}));ElMessage.success(`对账 RUN-${run.id} 已完成，发现 ${run.differences?.length||0} 条差异`);await load()}finally{actionLoading.value=false}}
function open(row:any){selected.value=row;drawer.value=true}
function prepareUpdate(row:any){selected.value=row;nextStatus.value=row.status==='OPEN'?'INVESTIGATING':'RESOLVED';note.value='';updateDialog.value=true}
async function updateStatus(){actionLoading.value=true;try{await api.patch(`/platform/reconciliation/differences/${selected.value.id}`,{status:nextStatus.value,note:note.value.trim()});ElMessage.success('差异处理状态已更新');updateDialog.value=false;drawer.value=false;await load()}finally{actionLoading.value=false}}
onMounted(load)
</script>
<template>
  <MBPageHeader title="对账中心" subtitle="账单、总账与模拟渠道之间的已持久化差异。"><template #actions><el-button type="primary" :loading="actionLoading" :disabled="!canRun" @click="runReconciliation">立即执行对账</el-button></template></MBPageHeader>
  <section class="mb-card table-card"><div class="filter-bar"><el-select v-model="query.status" clearable placeholder="全部状态"><el-option v-for="s in ['OPEN','INVESTIGATING','RESOLVED','WAIVED']" :key="s" :value="s" :label="s"/></el-select><el-button type="primary" @click="load">查询</el-button></div><el-table v-loading="loading" :data="rows" @row-click="open"><el-table-column prop="id" label="差异ID" width="100"/><el-table-column prop="differenceType" label="差异类型" min-width="190"/><el-table-column prop="referenceType" label="对象类型" width="130"/><el-table-column prop="referenceId" label="关联对象" min-width="170"/><el-table-column label="期望金额" width="140"><template #default="{row}">{{ money(row.currency,row.expectedAmountMinor) }}</template></el-table-column><el-table-column label="实际金额" width="140"><template #default="{row}">{{ money(row.currency,row.actualAmountMinor) }}</template></el-table-column><el-table-column prop="expectedStatus" label="期望状态" width="120"/><el-table-column prop="actualStatus" label="实际状态" width="120"/><el-table-column label="处理状态" width="130"><template #default="{row}"><MBStatusTag :status="row.status"/></template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button text type="primary" :disabled="!canResolve" @click.stop="prepareUpdate(row)">处理</el-button></template></el-table-column></el-table><el-empty v-if="!loading&&!rows.length" description="当前租户没有对账差异"/></section>
  <el-drawer v-model="drawer" size="min(560px, 92vw)" title="差异详情"><template v-if="selected"><div class="detail-heading"><h2 class="mono">DIFF-{{ selected.id }}</h2><MBStatusTag :status="selected.status"/></div><el-descriptions :column="1" border><el-descriptions-item label="差异类型">{{ selected.differenceType }}</el-descriptions-item><el-descriptions-item label="关联对象">{{ selected.referenceType }} / {{ selected.referenceId }}</el-descriptions-item><el-descriptions-item label="期望事实">{{ money(selected.currency,selected.expectedAmountMinor) }} · {{ selected.expectedStatus||'—' }}</el-descriptions-item><el-descriptions-item label="实际事实">{{ money(selected.currency,selected.actualAmountMinor) }} · {{ selected.actualStatus||'—' }}</el-descriptions-item><el-descriptions-item label="首次发现">{{ selected.firstSeenAt }}</el-descriptions-item><el-descriptions-item label="最后发现">{{ selected.lastSeenAt }}</el-descriptions-item></el-descriptions><h3>证据快照</h3><pre class="evidence">{{ evidence }}</pre><el-button v-if="canResolve" type="primary" @click="prepareUpdate(selected)">更新处理状态</el-button></template></el-drawer>
  <el-dialog v-model="updateDialog" title="更新差异处理状态" width="460px"><el-form label-position="top"><el-form-item label="目标状态"><el-select v-model="nextStatus" style="width:100%"><el-option v-for="s in ['OPEN','INVESTIGATING','RESOLVED','WAIVED']" :key="s" :label="s" :value="s"/></el-select></el-form-item><el-form-item label="处理说明（必填）"><el-input v-model="note" type="textarea" :rows="4" maxlength="1000" show-word-limit/></el-form-item></el-form><template #footer><el-button @click="updateDialog=false">取消</el-button><el-button type="primary" :loading="actionLoading" :disabled="!note.trim()||nextStatus===selected?.status" @click="updateStatus">确认更新</el-button></template></el-dialog>
</template>
<style scoped>.detail-heading{display:flex;align-items:center;gap:12px;margin-bottom:20px}.detail-heading h2{margin:0}.evidence{white-space:pre-wrap;word-break:break-word;padding:14px;border-radius:7px;background:#f6f8fb;color:#294469;font:12px/1.6 "Cascadia Mono",Consolas,monospace;margin:10px 0 20px}</style>
